import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String str_input = scanner.nextLine();
        StringBuilder temp_str = new StringBuilder();

        for (int pos = 0; pos < str_input.length(); pos++) {
            if (str_input.charAt(pos) == 'd' && pos + 2 < str_input.length()
                    && str_input.charAt(pos + 1) == 'o' && str_input.charAt(pos + 2) == 't') {
                temp_str.append('.');
                pos += 2;
            } else if (str_input.charAt(pos) == 'a' && pos + 1 < str_input.length()
                    && str_input.charAt(pos + 1) == 't') {
                temp_str.append('@');
                pos += 1;
            } else {
                temp_str.append(str_input.charAt(pos));
            }
        }

        StringBuilder final_output = new StringBuilder();

        if (temp_str.length() > 0) {
            char firstChar = temp_str.charAt(0);
            if (firstChar == '.') {
                final_output.append("dot");
            } else if (firstChar == '@') {
                final_output.append("at");
            } else {
                final_output.append(firstChar);
            }

            int at_flagged = 0;
            for (int q = 1; q + 1 < temp_str.length(); q++) {
                char currentChar = temp_str.charAt(q);
                if (currentChar == '@' && at_flagged == 0) {
                    final_output.append(currentChar);
                    at_flagged = 1;
                } else if (currentChar == '@' && at_flagged == 1) {
                    final_output.append("at");
                } else {
                    final_output.append(currentChar);
                }
            }

            char lastChar = temp_str.charAt(temp_str.length() - 1);
            if (lastChar == '.') {
                final_output.append("dot");
            } else if (lastChar == '@') {
                final_output.append("at");
            } else {
                final_output.append(lastChar);
            }
        }

        System.out.println(final_output.toString());
        scanner.close();
    }
}
